import { EventEmitter } from 'eventemitter3';
import { ISessionManagementSessionEndedReasonsTranslations, ISessionStatus, ISessionManagementEvents, ISessionManagementTranslations } from '../../types';
import { Component, Inject, Prop, Vue, Watch } from 'vue-property-decorator';
import AcceptPopup from '../accept-popup/index.vue';

@Component({
    components: { AcceptPopup }
})
export default class SessionEnded extends Vue {
    @Prop()
    public readonly translations: ISessionManagementTranslations;

    @Prop()
    public readonly sessionStatus: ISessionStatus;

    @Prop()
    public minStake: number;

    @Prop()
    public balance: number;

    @Prop()
    public suppressed: boolean;

    @Prop()
    public readonly events: EventEmitter<ISessionManagementEvents>;

    @Inject()
    public readonly stringifyTime: (seconds: number) => string;

    @Inject()
    public readonly stringifyBet: (bet: number) => string;

    public closed: boolean = true;

    public reasonTranslations: ISessionManagementSessionEndedReasonsTranslations;

    get visible(): boolean {
        return !this.suppressed && this.sessionStatus.SessionEnded && !this.closed;
    }

    get currentBet(): string {
        return this.stringifyBet(this.sessionStatus.CurrentBet);
    }

    get totalWinnings(): string {
        return this.stringifyBet(this.sessionStatus.TotalWinnings);
    }

    get netBalance(): string {
        return this.stringifyBet(this.sessionStatus.NetBalance);
    }

    public created(): void {
        this.reasonTranslations = this.translations.sessionEnded.timeExpired;
    }

    @Watch('sessionStatus', { immediate: true, deep: true })
    public onSessionStatusChanged(): void {
        if (!this.sessionStatus.SessionEnded) {
            this.closed = false;
        } else {
            if (((this.sessionStatus.MaxBet + this.sessionStatus.NetBalance) < this.minStake || this.balance < this.minStake) && this.sessionStatus.MaxBet !== 0) {
                this.reasonTranslations = this.translations.sessionEnded.balanceExpired;
            } else {
                this.reasonTranslations = this.translations.sessionEnded.timeExpired;
            }
        }
    }

    @Watch('suppressed', { immediate: false, deep: false })
    public suppressedChanged(surpessedValue: boolean): void {
        if (!surpessedValue && this.sessionStatus.SessionEnded) {
            this.closed = false;
        }
    }

    public onClosed(): void {
        this.closed = true;
        this.events.emit('session:ended:closed');
    }
}